{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Push for a higher general cap"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "a lower or no de minimis, and a tipping basket (once crossed, recovery from the first dollar)"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "NOT_ADDRESSED",
      "evidence": ""
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject applying the general cap and 18-month time limit to capacity and title."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve remedies for fraud, intentional or deliberate breach, title/fundamental matters, specific indemnities, and other negotiated exceptions"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Require specific, fair disclosure against the particular warranty, with enough detail for the Buyer to identify the nature and scope of the exception."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject the proposed bar for anything “known” by the Buyer or its advisers, including anything discoverable."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make delivery of the required final written consent and satisfaction of all conditions a condition precedent"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "No post-Completion release should substitute for this."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Treat amounts triggered by Completion or attributable to the pre-Completion period as Seller-borne, paid or provided for at Completion"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the specific indemnity to cover the full consequences of the matter"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "a specific indemnity for losses, response costs, claims and regulatory consequences arising from this incident."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Ensure any pre-Completion liabilities or unusual commitments are reflected in the completion accounts or expressly warranted"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "ensure an exclusive-remedy clause does not override agreed indemnities or prevent equitable relief where appropriate."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is a share-register entry, not a substitute for full title protection."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Ensure related claims are aggregated and the thresholds do not apply to fraud, deliberate concealment, title/fundamental warranties, tax, specific indemnities or other agreed carve-outs."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

